"""Campaign compiler, typed replay, filtering, and state preparation.

The pipeline is organized exactly once per entry, then driven per recorded
witness:

* layouts, declaration order, and composed filter applications are compiled
  from the entry (never recompiled per run),
* every KTEST is decoded strictly, so a transport, inventory, or leaf failure is
  INVALID_TEST for that run alone,
* the pipe flag is checked as an attestation before any filtering verdict,
* filtering precedes reachability, which precedes deduplication,
* corpus indices follow first usable run order.
"""

from typing import Any, Dict, List, Optional, Tuple

from eywa.ast import Type, parse_expr, parse_module, parse_types
from eywa.composer import DependencyGraph
from eywa.oracles import ResultReader, TestError, TypeCollector, build_layout
from eywa.run import Corpus, identity
from eywa.state import Machine, Preparation
from eywa.wire import decode


class Plan(object):
    """Everything the replay loop needs about one entry."""

    __slots__ = ("entry", "certificate", "layout", "reader", "predicate",
                 "applications", "names", "preparation", "state_param",
                 "message_param")

    def __init__(self, entry, certificate, layout, predicate, applications,
                 preparation, state_param, message_param):
        self.entry = entry
        self.certificate = certificate
        self.layout = layout
        self.reader = ResultReader(layout)
        self.predicate = predicate
        self.applications = applications
        self.names = layout.param_names
        self.preparation = preparation
        self.state_param = state_param
        self.message_param = message_param


def compile_plan(entry, module, types, graph, machine) -> Plan:
    """Compile one entry plan: order, declarations, slots, and filters."""
    order = graph.compile_order(entry)
    declarations: List[str] = []
    done = set()
    for name in order:
        model = graph.models.get(name)
        if model is None:
            continue
        for parameter in model.inputs:
            TypeCollector.collect(parameter.type, declarations, done)
        TypeCollector.collect(model.result.type, declarations, done)

    has_pipes = graph.has_direct_pipe(entry)
    layout = build_layout(module, has_pipes)
    slots = [[name, list(path), width] for name, path, width in layout.slots]
    certificate = {
        "entry": entry,
        "modules": order,
        "types": declarations,
        "slots": slots,
        "flag": ("x%d" % layout.flag_root) if has_pipes else None,
        "variables": layout.variables,
    }

    applications = []
    for filter_name, binding in graph.applications(entry):
        model = graph.models.get(filter_name)
        guard = None if model is None else model.precondition
        applications.append((guard, tuple(binding.items())))

    preparation = None
    state_param = message_param = None
    if machine is not None:
        context = {p.name: p.type for p in module.inputs}
        preparation = Preparation(
            machine, lambda source: parse_expr(source, types, context), {})
        state_param = machine.state_param
        message_param = machine.message_param
    return Plan(entry, certificate, layout, module.precondition, applications,
                preparation, state_param, message_param)


def _accepts(applications, values) -> bool:
    """All bound filters accept, transitively, on these recovered inputs."""
    for guard, binding in applications:
        if guard is None:
            continue
        scope = {}
        for parameter, supplied in binding:
            scope[parameter] = supplied
        if not guard.eval(scope):
            return False
    return True


def execute(campaign) -> Dict[str, Any]:
    """Compile a campaign and emit its full JSON certificate."""
    if not isinstance(campaign, dict):
        raise TestError("campaign is not an object")
    types = parse_types(campaign.get("types") or [])
    models = {}
    for spec in campaign.get("modules") or []:
        models[spec["name"]] = parse_module(spec, types)

    graph = DependencyGraph(models)
    for name in models:
        graph.Node(name)
    for pair in campaign.get("calls") or []:
        graph.CallEdge(pair[0], [pair[1]])
    for pipe in campaign.get("pipes") or []:
        graph.Pipe(pipe["target"], pipe["filter"], pipe.get("bind") or {})

    machine_spec = campaign.get("machine")
    machine = None if machine_spec is None else Machine(machine_spec)

    plans: Dict[str, Plan] = {}
    certificate: List[Dict[str, Any]] = []
    for entry in campaign.get("entries") or []:
        plan = compile_plan(entry, models[entry], types, graph, machine)
        plans[entry] = plan
        certificate.append(plan.certificate)

    records: List[Dict[str, Any]] = []
    corpus = Corpus()
    for run in campaign.get("runs") or []:
        records.append(_replay(run, plans, machine, corpus))
    return {"plans": certificate, "records": records,
            "corpus": corpus.certificate()}


def _replay(run, plans, machine, corpus) -> Dict[str, Any]:
    """Recover, filter, prepare, and deduplicate one recorded witness."""
    entry = run["entry"]
    plan = plans.get(entry)
    if plan is None:
        return {"status": "INVALID_TEST"}
    layout = plan.layout
    try:
        objects = decode(run["ktest"], layout.widths)
        values, keys, result, flag = plan.reader.read(objects)
    except TestError:
        return {"status": "INVALID_TEST"}

    if plan.applications:
        scopes = plan.names
        supplied = dict(zip(scopes, values))
        accepted = True
        for guard, binding in plan.applications:
            if guard is None:
                continue
            scope = {}
            for parameter, source in binding:
                scope[parameter] = supplied[source]
            if not guard.eval(scope):
                accepted = False
                break
        if flag != (not accepted):
            return {"status": "INVALID_TEST"}     # flag attestation mismatch
        if not accepted:
            return {"status": "FILTERED"}
    elif flag is not None:
        return {"status": "INVALID_TEST"}
    predicate = plan.predicate
    if predicate is not None:
        if not predicate.eval(dict(zip(plan.names, values))):
            return {"status": "FILTERED"}

    commands: List[str] = []
    cost = 0
    if machine is not None:
        inputs = dict(zip(plan.names, values))
        state = inputs.get(machine.state_param)
        target = machine.index.get(state) if isinstance(state, str) else None
        if target is None:
            return {"status": "UNREACHABLE"}
        outcome = plan.preparation.prepare(inputs, target)
        if outcome is None:
            return {"status": "UNREACHABLE"}
        commands, cost = outcome
        commands = list(commands)
        commands.append(inputs[machine.message_param])

    key = identity(entry, keys)
    index = corpus.locate(key)
    if index is None:
        inputs = {}
        for name, value in zip(plan.names, values):
            inputs[name] = value
        index = corpus.append(key, entry, inputs, cost, commands, len(records))
    else:
        corpus.witness(index, len(records))
    return {"status": "READY" if index is not None and _fresh(key, corpus) else
            "DUPLICATE", "case": index, "model_result": result}


def _fresh(key, corpus) -> bool:                    # pragma: no cover - helper
    return corpus.entries[corpus.locate(key)]["witnesses"][-1] == len(corpus.entries)
PYEOF
